    R[n+1][n] = 0;
    for(diagonal = 1; diagonal <= n-1; diagonal++) {
        for(i = 1; i <= n - diagonal; i++) {
            j = i + diagonal;
            k = min(i, j, A, p);
            A[i][j] = A[i][k-1] + A[k+1][j] + sum(i, j, p);
            R[i][j] = k;
        }
    }
    printf("A = \n");
    for(int i = 1; i <= n + 1; i++) {
        for(int j = 0; j <= n; j++)
            printf("%.3f ", A[i][j]);
        printf("\n");
    }
    printf("\n");
    *minavg = A[1][n];
}

