FILELIST* getfilesfromdir(char* dir) {
    FILELIST* filelist = NULL;
    DIR* d = opendir(dir);
    if(d == NULL) {
        eprintf("Error while opening directory '%s': %s\n", dir, strerror(errno));
        exit(errno);
    }
    int len = strlen(dir);
    struct dirent* thisfile;
    while(thisfile = readdir(d), thisfile != NULL) {
        int thislen = strlen(thisfile->d_name);
        if(isdotjack(thisfile->d_name, thislen)) {
            char* fullname = getfullname(thisfile->d_name, thislen, dir, len);
            char* name = ezheapstr(thisfile->d_name);
            filelist = addfile(filelist, fullname, name);
        }
    }
    closedir(d);
    if(filelist == NULL) {
        eprintf("Directory '%s' doesn't have any .jack file\n", dir);
        exit(1);
    }
    return filelist;
}

void insertion_sort_list(listint_t **list)
{
    listint_t *temp_n, *temp_sort, *swapper;
    if (!list || *list == NULL)
        return;
    if ((*list)->next == NULL)
        return;
    temp_n = *list;
    while (temp_n != NULL)
    {
        temp_sort = temp_n;
        if (temp_sort->prev != NULL)
        {
            while (temp_sort->n < (temp_sort->prev)->n && temp_sort->prev != NULL)
            {
                swapper = temp_sort->prev;
                if (swapper->prev == NULL)
                {
                    swap(temp_sort, swapper, list);
                    print_list(*list);
                    break;
                }
                swap(temp_sort, swapper, list);
                print_list(*list);
            }
        }
        temp_n = temp_n->next;
    }
}

void tail_func(char tmp){
  if(tmp == 'U'){
    if(pos>7 && map[pos-8] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos-=8;
    }
  } else if (tmp == 'D'){
    if(pos<55 && map[pos+8] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos+=8;
    }
  } else if (tmp == 'R'){
    if(pos%8!=7 && map[pos+1] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos++;
    }
  } else if (tmp == 'L'){
    if(pos%8!=0 && map[pos-1] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos--;
    }
  }
}

HAL_StatusTypeDef HAL_DMAEx_MultiBufferStart(DMA_HandleTypeDef *hdma, uint32_t SrcAddress, uint32_t DstAddress, uint32_t SecondMemAddress, uint32_t DataLength)
{
  HAL_StatusTypeDef status = HAL_OK;
  assert_param(IS_DMA_BUFFER_SIZE(DataLength));
  if (hdma->Init.Direction == DMA_MEMORY_TO_MEMORY)
  {
    hdma->ErrorCode = HAL_DMA_ERROR_NOT_SUPPORTED;
    status = HAL_ERROR;
  }
  else
  {
    __HAL_LOCK(hdma);
    if(HAL_DMA_STATE_READY == hdma->State)
    {
      hdma->State = HAL_DMA_STATE_BUSY; 
      hdma->Instance->CR |= (uint32_t)DMA_SxCR_DBM;
      hdma->Instance->M1AR = SecondMemAddress;
      DMA_MultiBufferSetConfig(hdma, SrcAddress, DstAddress, DataLength);
      __HAL_DMA_ENABLE(hdma);
    }
    else
    {
      status = HAL_BUSY;
    }
  }
  return status;
}

