    printf("cos(%i) es igual a %lf", X, (Suma_total + 1.0));
    return 0;
}

void * productor(){ 
    for (int i=0; i<10; i++){   
        sem_wait(&empty);                                                          
        sem_wait(&mutex);  
        int numero = rand()%101;    
        producirDato(numero);
        printf("Productor:\n");
        printf("Dato %d: %d\n", i+1, numero);
        sem_post(&mutex);                                  
        sem_post(&full);                                   
    }
    pthread_exit(NULL);                                   
}
